// Actual portable public state machine; no GPIO, serial port, network or credentials.
#include "../05-test/hx_failure_diag.h"
#include <cassert>
#include <cstdio>
#include <cstring>
#include <vector>
static bool start(HxFailureDiag &s, uint32_t anchor = 10000, bool eligible = true) { return hxfStart(s, 1922, anchor - 216, anchor, 0xFFFEC3, 1921, 1, eligible ? 0 : 3, 0, eligible, anchor + 1); }
static void finish(HxFailureDiag &s) { for (uint8_t i = 0; i < HXF_POINTS; ++i) { const uint32_t now = s.read_end_us + HXF_TARGET_US[i]; assert(hxfDue(s, now) == i); hxfSample(s, now, now + 1, i == 2); } }
static uint32_t reference(const std::vector<uint32_t> &words) { uint32_t table[256]; for (uint32_t i = 0; i < 256; ++i) { uint32_t x = i; for (unsigned j = 0; j < 8; ++j) x = x & 1 ? (x >> 1) ^ 0xEDB88320U : x >> 1; table[i] = x; } uint32_t crc = 0xFFFFFFFFU; for (uint32_t w : words) for (unsigned b = 0; b < 4; ++b) crc = table[(crc ^ (w >> (8 * b))) & 255] ^ (crc >> 8); return crc ^ 0xFFFFFFFFU; }
int main() {
  unsigned passed = 0;
  { HxFailureDiag s; assert(start(s)); assert(s.mode == HXF_HOLD && s.raw == -317 && s.bits24 == 0xFFFEC3 && s.rx == 1921 && s.err_before == 0 && s.err_after == 1 && s.next == 0); ++passed; }
  { HxFailureDiag s; start(s); finish(s); assert(s.mode == HXF_COMPLETE && s.stop_reason == HXF_STOP_TARGET && s.next == 12 && s.probe_end_us == 260001); for (unsigned i = 0; i < 12; ++i) assert(s.points[i].valid && !s.points[i].missed); assert(s.points[2].dout == 1 && s.points[3].dout == 0); ++passed; }
  { HxFailureDiag s; start(s); assert(hxfDue(s, 10075) == 2); assert(s.points[0].missed && s.points[1].missed && !s.points[0].valid); hxfSample(s, 10075, 10077, false); assert(hxfDue(s, 10078) == -1 && s.next == 3); ++passed; }
  { HxFailureDiag s; start(s); assert(hxfDue(s, 410000) == 11); hxfSample(s, 410000, 410010, true); assert(s.mode == HXF_COMPLETE && s.probe_end_us - s.read_end_us == 400010 && s.points[10].missed && !s.points[10].valid); ++passed; }
  { HxFailureDiag s; start(s); hxfSample(s, 10001, 10002, false); assert(s.next == 0 && !s.points[0].valid); ++passed; }
  { HxFailureDiag s; start(s, 10000, false); assert(s.mode == HXF_SKIPPED_BUSY && s.captured && s.next == 0 && s.phase_before == 3 && s.stop_reason == HXF_STOP_BUSY); HxFailureDiag copy = s; assert(!start(s, 20000)); hxfResume(s, 30000, 1923, true); assert(std::memcmp(&s, &copy, sizeof(s)) == 0); ++passed; }
  { HxFailureDiag s; hxfStop(s, HXF_STOP_RING, 0); assert(s.mode == HXF_CLOSED_NO_LINK && !s.captured && s.next == 0 && !start(s)); for (const auto &p : s.points) assert(!p.valid && !p.missed); ++passed; }
  { HxFailureDiag s; start(s); hxfDue(s, 10002); hxfSample(s, 10002, 10003, false); hxfStop(s, HXF_STOP_WINDOW, 10200); assert(s.mode == HXF_TRUNCATED && s.next == 1 && s.points[0].valid && !s.points[1].valid && !s.points[1].missed); hxfResume(s, 11000, 1923, true); hxfResume(s, 12000, 1924, true); assert(s.resume_valid && s.resume_start_us == 11000 && s.resume_seq == 1923); ++passed; }
  { HxFailureDiag s; start(s, 0xFFFFFF00U); finish(s); assert(s.mode == HXF_COMPLETE && hxdiagDelta(s.probe_end_us, s.read_end_us) == 250001); hxfResume(s, s.probe_end_us + 123, 1923, true); assert(hxdiagDelta(s.resume_start_us, s.probe_end_us) == 123); ++passed; }
  { HxDiagState ring; hxdiagBegin(ring, 0); HxDiagRecord r = {}; r.accepted = 1; r.raw = -160000; r.start_us = 1000; r.end_us = 1200; hxdiagObserve(ring, r); r.raw = -317; r.start_us = 2000; r.end_us = 2200; hxdiagObserve(ring, r); assert(ring.trigger_seq == 2 && ring.trigger_flags == HXD_JUMP); HxFailureDiag s; hxfStart(s, 3, 3000, 3216, 0xFFFEC3, 2, 1, 0, 0, true, 3217); r.accepted = 0; r.start_us = 3000; r.end_us = 3216; hxdiagObserve(ring, r); assert(s.seq == 3 && ring.trigger_seq == 2 && ring.records[hxdiagIndex(ring, 2)].seq == s.seq); ++passed; }
  { HxFailureDiag s; start(s); finish(s); hxfResume(s, 270000, 1923, true); std::vector<uint32_t> words = {s.mode,s.stop_reason,s.captured,s.seq,s.read_start_us,s.read_end_us,s.probe_start_us,s.probe_end_us,s.resume_start_us,s.resume_seq,s.resume_valid,s.rx,s.err_before,s.err_after,s.bits24,static_cast<uint32_t>(s.raw),s.phase_before,s.cal_before,s.next}; for (uint32_t i = 0; i < HXF_POINTS; ++i) { const auto &p = s.points[i]; words.insert(words.end(), {i,HXF_TARGET_US[i],p.begin_us,p.end_us,p.dout,p.valid,p.missed}); } assert(words.size() == 103 && hxfCrc(s) == reference(words)); s.points[4].dout ^= 1; assert(hxfCrc(s) != reference(words)); ++passed; }
  { HxFailureDiag s; start(s); finish(s); hxfResume(s, 270000, 1923, true); const HxFailureDiag copy = s; assert(!start(s) && hxfDue(s, 900000) == -1); hxfStop(s, HXF_STOP_RING, 900000); hxfSample(s, 900000, 900001, false); (void)hxfCrc(s); assert(std::memcmp(&s, &copy, sizeof(s)) == 0); ++passed; }
  { HxFailureDiag s; start(s); hxfStop(s, HXF_STOP_RING, 10200); const uint32_t crc = hxfCrc(s); const HxFailureDiag copy = s; hxfResume(s, 15000, 1923, false); assert(!s.resume_valid && hxfCrc(s) == crc && std::memcmp(&s, &copy, sizeof(s)) == 0); ++passed; }
  { HxFailureDiag s; start(s); assert(hxfDue(s, 10002) == 0); hxfSample(s, 10075, 10078, true); assert(s.points[0].missed && s.points[1].missed && !s.points[0].valid && s.points[2].valid && s.points[2].begin_us == 10075); ++passed; }
  { HxFailureDiag s; HxDiagState ring; hxdiagBegin(ring, 0); hxdiagFreeze(ring, 123456, HXD_POST_FULL); if (s.mode == HXF_WAITING) hxfStop(s, HXF_STOP_RING, ring.freeze_us); const uint32_t first_export = hxfCrc(s); const HxFailureDiag copy = s; hxfStop(s, HXF_STOP_RING, 123999); assert(s.mode == HXF_CLOSED_NO_LINK && hxfCrc(s) == first_export && std::memcmp(&s, &copy, sizeof(s)) == 0); ++passed; }
  std::printf("%u native HX failure-trace cases passed; trace=%zu bytes. Not GPIO/physical timing validation.\n", passed, sizeof(HxFailureDiag));
}
